"use strict";(self.webpackChunkkmworks_website=self.webpackChunkkmworks_website||[]).push([["828"],{5129(e){e.exports=JSON.parse('{"version":{"pluginId":"kmrs","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"kmrs":[{"type":"link","href":"/kmrs/","label":"Introduction","docId":"intro","unlisted":false},{"type":"link","href":"/kmrs/installation","label":"Installation","docId":"installation","unlisted":false},{"type":"link","href":"/kmrs/configuration","label":"Configuration","docId":"configuration","unlisted":false},{"type":"link","href":"/kmrs/webui","label":"Serving a web UI","docId":"webui","unlisted":false},{"type":"link","href":"/kmrs/search","label":"Search","docId":"search","unlisted":false},{"type":"link","href":"/kmrs/compatibility","label":"Compatibility","docId":"compatibility","unlisted":false},{"type":"link","href":"/kmrs/enhancements","label":"Enhancements","docId":"enhancements","unlisted":false},{"type":"link","href":"/kmrs/limitations","label":"Known limitations","docId":"limitations","unlisted":false},{"type":"link","href":"/kmrs/development","label":"Development","docId":"development","unlisted":false}]},"docs":{"compatibility":{"id":"compatibility","title":"Compatibility","description":"The compatibility target is komga 1.27.1: the Flyway migrations, the OpenAPI document, and the behavior fixtures are taken from that release, and API behavior is ported from it. Improvements and intentional behavior differences are listed under Enhancements; accepted gaps under Known limitations.","sidebar":"kmrs"},"configuration":{"id":"configuration","title":"Configuration","description":"kmrs --help lists the CLI flags (--config-dir, --port). The configuration file is always /config.toml; on first start it is generated from the built-in defaults, carrying over values from the Java komga\'s application.yml/application.yaml found in the same directory.","sidebar":"kmrs"},"development":{"id":"development","title":"Development","description":"sync-migrations looks for a komga source checkout next to this repo by default; KOMGAREPODIR can be used to point elsewhere. The checkout should be at the compatibility target (1.27.1).","sidebar":"kmrs"},"enhancements":{"id":"enhancements","title":"Enhancements","description":"Improvements kmrs adds on top of Java parity, plus intentional behavior differences. Accepted gaps that are not planned to be closed are listed under Known limitations.","sidebar":"kmrs"},"installation":{"id":"installation","title":"Installation","description":"Docker","sidebar":"kmrs"},"intro":{"id":"intro","title":"Introduction","description":"kmrs is a drop-in, API-compatible reimplementation of the Komga comic/manga server in Rust: a single static binary.","sidebar":"kmrs"},"limitations":{"id":"limitations","title":"Known limitations","description":"Places where kmrs has not matched the Java version and does not plan to \u2014 accepted gaps. Improvements and intentional behavior differences are listed under Enhancements. Scope exclusions are intentional and not listed here either: no web UI in the standalone binary (the docker image bundles the kmweb UI), and no actuator endpoints or metrics that only expose JVM/Spring internals (beans, conditions, env, configprops, loggers, mappings, heapdump, threaddump, system./http.server.requests meters, jvm. beyond jvm.memory.used and the like).","sidebar":"kmrs"},"search":{"id":"search","title":"Search in kmrs","description":"kmrs ports komga\'s Lucene search to tantivyberserk, tagONGOING, prefixes, wildcards, phrases) and the multilingual analyzer chain behave like the Java version. This document describes the analyzer chain and the recall extensions kmrs adds on top of it.","sidebar":"kmrs"},"webui":{"id":"webui","title":"Serving a web UI with kmrs","description":"kmrs does not embed a web UI in the binary (the release docker image bundles","sidebar":"kmrs"}}}}')}}]);